import { BrowserRouter, Route, Routes } from "react-router-dom";
import Home_header from "./website/components/Home_header";
import Home from "./website/pages/Home";
import Footer from "./website/components/Footer";
import About from "./website/pages/About";
import Header from "./website/components/Header";
import Contacts from "./website/pages/Contacts";
import Course from "./website/pages/Course";
import Team from "./website/pages/Team";
import Testimonial from "./website/pages/Testimonial";
import Pnf from "./website/pages/Pnf";

function App() {
  return (
    <div className="App">
       <BrowserRouter>
        <Routes>
          <Route path="/" element={<><Home_header/><Home/><Footer/></>}></Route>
          <Route path="/about" element={<><Header/><About/><Footer/></>}></Route>
          <Route path="/contacts" element={<><Header/><Contacts/><Footer/></>}></Route>
          <Route path="/courses" element={<><Header/><Course/><Footer/></>}></Route>
          <Route path="/team" element={<><Header/><Team/><Footer/></>}></Route>
          <Route path="/testimonial" element={<><Header/><Testimonial/><Footer/></>}></Route>
          <Route path="*" element={<><Header/><Pnf/><Footer/></>}></Route>
        </Routes>
       </BrowserRouter>
    </div>
  );
}

export default App;
